INSERT INTO public.socios VALUES ('4dae8de3-559b-441b-b5fa-0ad18758e093', 'HAKKI', 'hakki', 'Plataforma salvadoreña de gestión de eventos presenciales, virtuales e hábridos que integra tecnologáa inmersiva, inteligencia artificial y herramientas digitales para la planificación, organización y ejecución de eventos. Fue desarrollada en El Salvador y ha sido utilizada en congresos, ferias, ruedas de negocio y eventos tecnológicos de alcance nacional e internacional.', '{EventTech,"Eventos virtuales","Eventos hábridos","Inteligencia Artificial","Realidad Extendida","Networking Digital"}', '{"Gestión de eventos","Plataforma de registro","Venta de boletos","Networking empresarial","Eventos virtuales","Eventos hábridos","Automatización de eventos","Planificación con IA"}', 'https://hakki.fun/', 'https://www.facebook.com/hakkisv', 'https://www.linkedin.com/company/hakki-sv', '', 'https://www.instagram.com/hakki.sv', '', '', '', '	https://hakki.fun/images/hakkiCompound.png', 'gh@hakki.sv', '', '', 'AlDia', true, '2026-05-29 16:18:44.51647+00', '2026-05-29 16:18:44.51647+00', DEFAULT);
