INSERT INTO public.socios VALUES ('eceb4567-b861-4412-8a2d-8610920b833e', 'INNOGEN CAPITAL', 'innogen-capital', 'Firma salvadoreña de capital de riesgo (Venture Capital) fundada en 2018, especializada en invertir en startups tecnológicas en etapas tempranas de Latinoamérica. Su enfoque principal estí en empresas de alto crecimiento en sectores como FinTech, HealthTech, AgTech, PropTech, SaaS, E-Commerce e Inteligencia Artificial. Administra fondos de inversión enfocados en impulsar el ecosistema tecnológico de Centroamérica y Latinoamérica mediante capital inteligente, mentoráa y conexiones estratégicas.', '{"Venture Capital",FinTech,HealthTech,AgTech,PropTech,SaaS,E-Commerce,"Inteligencia Artificial","Angel Investment","Portfolio Management"}', '{"Inversión en startups","Capital semilla","Venture Capital","Mentoráa empresarial","Aceleración de empresas","Gestión de portafolios","Conexiones estratégicas para escalamiento"}', 'https://innogencapital.com/', '', 'https://www.linkedin.com/company/innogen-capital', '', '', '', '', 'San Salvador, El Salvador', 'https://media.licdn.com/dms/image/v2/D4E0BAQF8ElcF4KJE3A/company-logo_200_200/B4EZr_CjhoIoAI-/0/1765215451668/innogen_capital_logo?e=2147483647&v=beta&t=Ym0CjZGTKt2gl5yYvJCN2OZX8pkot186qxoTIrswKtc', 'info@innogencapital.com', '', '', 'AlDia', true, '2026-05-29 17:10:25.22739+00', '2026-05-29 17:10:25.22739+00', DEFAULT);
INSERT INTO public.socios VALUES ('51e4b6c9-27c7-4720-982b-e58639e3cd53', 'CONSORCIO INDUSTRIAL INDEPENDENCIA, S.A. DE .C.V ', 't-box', 'Consorcio Industrial Independencia (TBOX) son un grupo de personas que trabajan continuamente para brindar a sus socios educativas propuestas que faciliten el aprovechamiento de la tecnologáa para transformar la enseñanza y el aprendizaje. En TBOX les gusta trabajar con los que creen en el futuro debe estar al alcance de las nuevas generaciones.', '{"Tecnologáa educativa","Innovación educativa","Transformación digital en educación","Plataformas tecnológicas","Formación digital"}', '{"implementación de soluciones educativas tecnológicas","Capacitación en herramientas digitales","Desarrollo de plataformas educativas","Consultoráa en educación digital","Integración de tecnologáa en instituciones educativas"}', 'https://www.tboxplanet.com/en/home', 'https://www.facebook.com/tboxplanet', 'https://www.linkedin.com/company/tboxplanet', '', 'https://www.instagram.com/tboxplanet', 'https://www.youtube.com/@tboxplanet', '2505-8269', 'Frente a, Embajada de España, Calle La Reforma No. 179, San Salvador, El Salvador', 'https://www.casatic.org/gallery\Socios\e8f38c53-cd8e-42b0-8de6-d45562fbb0cf.png ', 'info@tboxplanet.com', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4764.7590501332625!2d-89.233286!3d13.693348999999998!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f633025ec381cb5%3A0xe9ecd3ceeafe09a3!2sTBox!5e1!3m2!1ses!2ssv!4v1776787341798!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-21 16:02:42.465132+00', '2026-04-21 17:46:38.542781+00', DEFAULT);
INSERT INTO public.socios VALUES ('479c746b-77cf-4de2-9da1-d4538d96aae7', 'INSPIRETECH 1923', 'inspiretech-1923', 'Empresa salvadoreña especializada en transformación digital, innovación tecnológica y desarrollo de soluciones empresariales. Su enfoque estí orientado a ayudar a las organizaciones a acelerar su adopción tecnológica mediante consultoráa estratégica, automatización de procesos y desarrollo de soluciones digitales.', '{"Transformación Digital","Innovación Tecnológica","Consultoráa IT","Automatización de Procesos","Desarrollo de Software","Estrategia Digital"}', '{"Consultoráa tecnológica","Desarrollo de software","Automatización empresarial","Transformación digital","Gestión de proyectos tecnológicos","Innovación empresarial"}', 'https://inspiretech1923.com', '', 'https://www.linkedin.com/company/inspiretech1923', '', '', '', '', 'San Salvador, El Salvador', 'https://media.licdn.com/dms/image/v2/D560BAQF89UWQLpPw4g/company-logo_100_100/B56ZWnGYscHsAU-/0/1742265224365/inspiretech1923_logo?e=2147483647&v=beta&t=QrtMm7_VPxArTc4TON-Q_WeKoTJs6ca5ok8PK78moTY', 'info@inspiretech1923.com', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d304921.9165092816!2d-89.36699570008753!3d13.7108142186905!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f6330bfffa34d4b%3A0x6de7f8f991e805e8!2sSan%20Salvador%20Centro!5e1!3m2!1ses!2ssv!4v1780074993962!5m2!1ses!2ssv', '', 'AlDia', true, '2026-05-29 17:20:04.335971+00', '2026-05-29 17:20:04.335971+00', DEFAULT);
INSERT INTO public.socios VALUES ('51103698-3ee4-4f71-9eb5-4b7feb13e0eb', 'Asociación SVNet', 'asociacion-svnet', 'Asociación SVNET es una organización que administra los nombres de dominio del nivel superior SV en Internet en forma eficiente, continúa, segura y confiable, y que lidera, promueve, colabora, apoya y participa en el desarrollo tecnológico y de Internet en El Salvador.', '{Desarrollo}', '{"Registro de dominios .sv","Gestión de DNS","Capacitación en tecnologáas de Internet","Desarrollo de proyectos tecnológicos","Promoción de innovación digital"}', 'https://www.svnet.org.sv', 'https://www.facebook.com/svnet.sv', 'https://www.linkedin.com/company/svnet', 'https://twitter.com/svnet_sv', '', 'https://www.youtube.com/@SVNet', '', 'Calle La Reforma #249, Colonia San Benito, San Salvador, El Salvador', 'https://www.casatic.org/gallery\Socios\85ceb18c-8808-4c42-a8df-014484de23a8.png ', 'info@svnet.org.sv', '', '', 'AlDia', true, '2026-03-13 15:25:38.442188+00', '2026-04-21 17:37:45.827186+00', DEFAULT);
