INSERT INTO public.socios VALUES ('8df132b4-8070-4e41-918c-af50c75f4c7c', 'Aracari Studios', 'aracari-studios', 'Aracari Studios es el socio adecuado para startups, empresas y organizaciones de impacto social que buscan crear nuevas herramientas digitales, servicios o estrategias de innovación y transformación digital para toda la empresa. Todo con un enfoque centrado en el ser humano.', '{Desarrollo}', '{"Desarrollo de software a la medida","Desarrollo de aplicaciones web","Desarrollo de aplicaciones móviles","Staff augmentation de talento tecnológico","Automatización de procesos con IA"}', 'https://www.aracaristudios.com/', '', 'https://www.linkedin.com/company/aracaristudios', '', '', '', '2535 1846', '"World Trade Center, Calle El Mirador, 87 Avenida Norte, Colonia Escalón, San Salvador, El Salvador', 'https://www.casatic.org/gallery\Socios\acari.png', 'hello@aracaristudios.com', '', '', 'AlDia', true, '2026-03-11 21:24:16.572354+00', '2026-04-21 17:37:42.916578+00', DEFAULT);
INSERT INTO public.socios VALUES ('ce40fc65-1da1-4f64-9a77-92d61ac4bbf9', 'EON Consultant', 'eon-consultant', 'Cualquiera puede crear un sitio web o gestionar cuentas en redes sociales, recibir el pago y pasar al siguiente cliente. Menos del 3% de los llamados expertos pueden hacer eso mientras entienden tu negocio y obtienen resultados medibles. Por eso trabajamos usando los avances tecnológicos y la la psicologáa humana para que los complejos procesos de crear, mantener o expandir tu negocio en lánea se traduzcan en pasos simples que tu empresa pueda seguir.', '{"Business Development","Marketing Digital",SEO,SEM,Branding,"Desarrollo Web"}', '{"Consultoráa empresarial","Desarrollo web","Gestión de redes sociales","Publicidad digital","Estrategia de marketing","Contenido digital"}', 'https://eonconsultant.com', 'https://www.facebook.com/eonconsultant', 'https://www.linkedin.com/company/eon-consultant', '', 'https://www.instagram.com/eonconsultant', '', '+506 2226-6550', 'Sector Los Sauces, San Jos´┐¢r, Provincia de San Jos´┐¢r, Costa Rica', 'https://eonconsultant.com/wp-content/uploads/2023/12/EON_1080X1080_Blue-150x150.png', '', '', '', 'AlDia', true, '2026-03-09 22:01:15.606427+00', '2026-03-11 16:24:52.483504+00', DEFAULT);
