INSERT INTO public.socios VALUES ('b1dbef09-64e4-40f4-b4d0-b69e24f91840', 'DATAGUARD, S.A. DE C.V.', 'dataguard', 'Empresa proveedora de servicios infomíticos que permitan satisfacer las necesidades de sus clientes, brindando la mejor solución y excelente calidad en el producto desarrollado.', '{"Data center (Cloud Services)","Continuidad de negocio (DRP",BRP),Ciberseguridad,"Outsourcing de TI","Integración de soluciones IT","Infraestructura tecnológica"}', '{"ervicios de data center (colocation y cloud)","Respaldo y resguardo de información","Seguridad de redes","Soporte multiplataforma","Consultoráa en continuidad de negocio","Servicios de outsourcing IT"}', 'https://dataguardgroup.com/', 'https://www.facebook.com/Dataguardgroup/', 'https://www.linkedin.com/company/dataguard-sv/', '', '', '', '2264-8442', ' World Trade Center San Salvador, San Salvador', 'https://www.casatic.org/gallery\Socios\8896699d-cb84-4fa1-887e-526dca4e65a3.png ', 'jbonilla@dataguardgroup.com', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3876.161096954473!2d-89.2409429!3d13.7086911!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f632fddfb6028ef%3A0x16176524b1181e51!2sDATAGUARD%20GROUP!5e0!3m2!1ses!2ssv!4v1773941084014!5m2!1ses!2ssv', '', 'AlDia', true, '2026-03-19 17:25:24.076175+00', '2026-03-19 17:25:24.076175+00', DEFAULT);
