INSERT INTO public.socios VALUES ('d57d8359-21d7-4e28-b9c3-ae56e9acb2c2', 'UNIVERSIDAD DE ORIENTE (UNIVO)', 'univo', 'Su actividad principal son los servicios educativos a nivel superior y se rige por la Ley de Educación Superior, su reglamento y demís leyes conexas: no pudieron intervenir en actividades religiosas o poláticas de ninguna naturaleza. Sus funciones bísicas son: la Docencia, Investigación y proyección social.', '{"Educación superior","Investigación acad´┐¢rmica","Formación profesional","Desarrollo acad´┐¢rmico","Proyección social"}', '{"Programas de educación superior","Carreras universitarias","Investigación acad´┐¢rmica","Actividades de proyección social","Formación profesional"}', 'https://www.univo.edu.sv', 'https://www.facebook.com/UNIVOSM', 'https://www.linkedin.com/school/universidad-de-oriente-sv-/', 'https://x.com/univosm', 'https://www.instagram.com/univosm/', 'https://www.youtube.com/@UNIVOSM', '7488-5902', ' 4ta Calle Poniente #705, San Miguel, El Salvador.', 'https://www.casatic.org/gallery\Socios\ae02162e-46e7-4499-9d62-12ce4ab6a73a.png ', 'info@univo.edu.sv', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4769.013548142624!2d-88.1836557!3d13.4817728!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f7b2a66689978cd%3A0x848a5908c440c41b!2sUniversidad%20de%20Oriente!5e1!3m2!1ses!2ssv!4v1776287621818!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-15 21:18:06.733475+00', '2026-04-15 21:18:06.733475+00', DEFAULT);
INSERT INTO public.socios VALUES ('c8b42b69-3e87-41d7-b23a-9aaf448995e0', 'UNIVERSIDAD FRANCISCO GAVIDIA', 'ufg', 'UFG estí comprometida con una formación profesional de educación superior sustentada en tres pilares: Tecnologáa, ya que la sociedad de la Información y conocimiento funciona a escala global bajo paradigmas tecnológicos: Innovación, lo que supone utilizar al míximo las expresiones de imaginación y creatividad; y Calidad, como principio y fundamento de un quehacer acad´┐¢rmico que busca dar mís de sá tras la excelencia.', '{"Educación superior",Tecnologáa,Innovación,"Formación profesional","Calidad acad´┐¢rmica"}', '{"Programas de pregrado","Programas acad´┐¢rmicos","Investigación acad´┐¢rmica","Educación continua","Formación profesional"}', 'https://ufg.edu.sv/', 'https://www.facebook.com/ufgoficial', 'https://www.linkedin.com/school/ufgoficial/', 'https://x.com/ufgoficial', 'https://www.instagram.com/ufg.oficial/', 'https://www.youtube.com/user/redsocialufg', '2209-2874', 'Calle El Progreso y Avenida Las Am´┐¢rricas, San Salvador, El Salvador', 'https://www.casatic.org/gallery\Socios\a7520586-5f67-4e74-b92b-5f831a6cfd46.png ', 'contactcenter@ufg.edu.sv', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4764.659055111902!2d-89.2224593240822!3d13.698283186688062!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f6330449b49107b%3A0xb739e2c73c1004f6!2sUniversidad%20Francisco%20Gavidia!5e1!3m2!1ses!2ssv!4v1776784793550!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-21 15:16:55.304327+00', '2026-04-21 15:20:07.454081+00', DEFAULT);
INSERT INTO public.socios VALUES ('3419ef5f-ca3f-4c28-8832-97f8c1971d4f', 'UNIVERSIDAD GERARDO BARRIOS', 'ugb', 'Fundada por hombres y mujeres emprendedores, quienes se asociaron y formaron EMPRESA, (Empresarios migueleños para la Educación S.A.), creando la Sede Central de la Universidad el 05 de diciembre de 1981, la cual estí ubicada en las instalaciones de la casa donde nació Juan Jos´┐¢r Cañas.', '{"Educación superior","Formación profesional","Investigación acad´┐¢rmica","Desarrollo acad´┐¢rmico","Proyección social"}', '{"Programas de pregrado","Programas acad´┐¢rmicos","Investigación universitaria","Educación continua","Formación profesional"}', 'https://www.ugb.edu.sv/', 'https://www.facebook.com/ugb.edu.sv', 'https://www.linkedin.com/school/universidad-gerardo-barrios', '', 'https://www.instagram.com/ugb_sv', 'https://www.youtube.com/@UGBsv', '2645-6500', 'calle Las Flores y Avenida Las Magnolias Colonia Escolín. San Miguel.', 'https://www.casatic.org/gallery\Socios\f8d0678d-4c52-4735-840f-e44f4be6af98.png ', 'rectoria@ugb.edu.sv', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d4768.87651918889!2d-88.19213289999999!3d13.488637999999998!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f7b2a58d2095515%3A0xfb0914d1181e605f!2sUniversidad%20Gerardo%20Barrios!5e1!3m2!1ses!2ssv!4v1776785126650!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-21 15:25:34.10215+00', '2026-04-21 15:25:34.10215+00', DEFAULT);
INSERT INTO public.socios VALUES ('c672b414-1f55-4337-b438-2986181e16ea', 'UNIVERSIDAD PEDAGOGICA DE EL SALVADOR ''DR. LUIS ALONSO APARICIO''', 'pedagogica', 'Una Universidad capaz de contribuir al desarrollo humano sostenible del paás por medio de la cooperación con los sectores involucrados; dispuesta a fomentar la comprensión y la tolerancia; comprometida con la difusión y popularización del conocimiento y la cultura; con la príctica de la investigación cientáfica e innovación tecnológica.', '{"Educación superior","Formación docente","Investigación cientáfica","Innovación tecnológica","Desarrollo humano"}', '{"Programas de pregrado","Programas acad´┐¢rmicos","Investigación universitaria","Educación continua","Formación profesional"}', 'https://www.pedagogica.edu.sv/', 'https://www.facebook.com/pedagogica', '', 'https://x.com/pedagogicaU', 'https://www.instagram.com/pedagogicasv', 'https://www.youtube.com/user/PedagogicaElSalvador', '2205 8100', '25 Av. Norte y Diagonal Hector Silva, San Salvador, San Salvador, El Salvador', 'https://www.casatic.org/gallery\Socios\7c988c21-f75b-4573-88a5-f84395fbda91.png ', 'info@pedagogica.edu.sv', 'https://www.google.com/maps/embed?pb=!1m12!1m8!1m3!1d1684.4953402608885!2d-89.20297029393872!3d13.707493239238802!3m2!1i1024!2i768!4f13.1!2m1!1suniversidad%20pedagogica!5e1!3m2!1ses!2ssv!4v1776785585234!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-21 15:33:14.530288+00', '2026-04-21 15:33:14.530288+00', DEFAULT);
INSERT INTO public.socios VALUES ('6ebd43d5-dbcf-4e9a-a5ca-f91d0c8c619c', 'UNIVERSIDAD SALVADOREÑA ALBERTO MASFERRER', 'usam', 'Fundada el 24 de noviembre de 1979 por un grupo visionario de profesionales en diferentes íreas, siendo la primera universidad privada que inclusionó en el írea de salud, con carreras como Cárugia Dental, Medicina, Cárugia, Quámica y Farmacia, entre otras.', '{"Educación superior","Ciencias de la salud","Formación profesional","Investigación acad´┐¢rmica","Desarrollo acad´┐¢rmico"}', '{"Programas de pregrado","Carreras universitarias","Formación en salud","Investigación universitaria","Educación continua"}', 'https://www.usam.edu.sv/', 'https://www.facebook.com/usamelsalvador', 'https://www.linkedin.com/company/usamsv', 'https://x.com/usamelsalvador', 'https://www.instagram.com/usamelsalvador', 'https://www.youtube.com/c/USAM-ES', '2231-9600', '19 Av. Nte. entre 3 a Calle Pte. y Alameda Juan Pablo II, San Salvador, El Salvador.', 'https://www.casatic.org/gallery\Socios\ac87a842-f948-4c46-8107-64ac1f32ae41.png ', 'coordinadorcomputacion@usam.edu.sv', 'https://www.google.com/maps/embed?pb=!1m16!1m12!1m3!1d1191.1456421969567!2d-89.2011630732603!3d13.702056176204383!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!2m1!1susam!5e1!3m2!1ses!2ssv!4v1776785956944!5m2!1ses!2ssv', '', 'AlDia', true, '2026-04-21 15:39:28.090922+00', '2026-04-21 15:39:28.090922+00', DEFAULT);
INSERT INTO public.socios VALUES ('36252670-6b2f-4be1-9906-89d332c05958', 'Unplug Studio', 'unplug-studio', 'Unplug Studio nace de un deseo de reinventarse y explorar nuevas metodologáas de trabajo, que est´┐¢rn en el ''Balance de trabajo en la vida'' y eso les permite a ellos proveerla información centralizada y la gran calidad de servicios digitales, permitiendo a sus clientes desconectarse de sus preocupaciones y convertir la tecnologáa es una herramienta que le permita cumplir sus metas.
