INSERT INTO public.socios VALUES ('76e54270-4eb3-4b13-a554-73fb60880011', 'TIGO EL SALVADOR', 'tigo', 'Compañáa salvadoreña, comprometida a invertir en la transformación digital de El Salvador a trav´┐¢rs de productos y servicios innovadores. Tigo es la marca comercial de la empresa Millicom que tiene presencia en el paás desde 1992 cuando invirtió en Telemóvil de El Salvador y desde entonces ocupa el puesto #1 en el paás en servicios de tecnologáa móvil y ofrece servicios digitales integrales tales como comunicaciones móviles de voz, televisión por cable, internet de alta velocidad y servicios financieros móviles a mís del 45% de la población.', '{Telecomunicaciones,"Internet de alta velocidad","Televisión por cable","Servicios móviles","Servicios financieros digitales"}', '{"Telefonáa móvil","Internet residencial y empresarial","Televisión por suscripción","Servicios financieros móviles","Soluciones digitales integrales"}', 'https://www.tigo.com.sv/', 'https://www.facebook.com/tigosv', '', '', '', '', '2500-4600', 'Bulevar Santa Elena, Antiguo Cuscatlín, La Libertad, El Salvador', 'https://www.casatic.org/gallery\Socios\b33e5a34-9391-4dda-8b50-9d2bf20cf0dd.png ', 'msalinas@sc.tigo.com', '', '', 'AlDia', true, '2026-04-21 16:16:18.503367+00', '2026-04-21 16:16:18.503367+00', DEFAULT);
INSERT INTO public.socios VALUES ('35bcc944-08f4-4121-b0bc-b27c021ad53e', 'CONSORCIO INDUSTRIAL INDEPENDENCIA, S.A. DE C.V.', 'consisa', 'Consultores en Sistemas (Grupo CONSISA) es una empresa con 30 años de operación, con gean experiencia en el campo de la tecnologáa de información orientada a proveer soluciones de negocios. Ademís de su experiencia, proponen herramientas que les permitan agilizar sus procesos.', '{"Servicios educativos","Distribución de material didíctico","Comercialización de contenido educativo","Recursos educativos digitales","Gestión de contenidos educativos"}', '{"Importación de libros y materiales educativos","Distribución de recursos educativos","Comercialización de contenido digital educativo","Servicios de apoyo educativo","Gestión de proyectos educativos"}', 'http://www.consisa.com', 'https://www.facebook.com/GrupoConsisa', 'https://www.linkedin.com/company/grupo-consisa/?originalSubdomain=sv', '', '', '', '2505 6000', 'Dirección: Edificio Gran Plaza, Local 408 Boulevard del Hipódromo, col. San Benito San Salvador, El Salvador', 'https://www.casatic.org/gallery/Socios/f84f715e-d876-48d4-8cd3-1621e05a7583.png', 'info@consisa.com', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d242.27496661359126!2d-89.23556931339299!3d13.694239303776769!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x8f63303a94183cd5%3A0xd6866b9ef77b784f!2sGrupo%20CONSISA%20El%20Salvador!5e0!3m2!1ses!2ssv!4v1773934631383!5m2!1ses!2ssv', '', 'AlDia', true, '2026-03-19 15:44:32.119688+00', '2026-04-21 17:44:34.603404+00', DEFAULT);
